  function pageKind() {
    var p = (location.pathname || "").replace(/\/+$/, "");
    if (/\/zoeken$/.test(p) || /\/zoeken\.html$/.test(p)) return { type: "zoeken" };
    var vm = p.match(/\/vak\/([^/.]+)/);
    if (vm) return { type: "vak", trade: vm[1] };
    if (p === "/stacks" || p === "" || /\/stacks\/index(\.html)?$/.test(p)) return { type: "index" };
    return { type: "other" };
  }

  function query() {
    try { return (new URLSearchParams(location.search).get("q") || "").trim().toLowerCase(); }
    catch (e) { return ""; }
  }

  function matchesQuery(e, q) {
    if (!q) return true;
    var blob = [e.title, e.description, e.trade, e.tradeLabel, e.companyName, e.displayLabel, e.sizeNote]
      .concat((e.tools || []).map(function (t) { return t.name + " " + t.role; }))
      .join(" ")
      .toLowerCase();
    return blob.indexOf(q) !== -1;
  }

  function alreadyThere(slug) {
    return !!document.querySelector('[data-extra-slug="' + slug + '"], a[href="/stacks/stack/' + slug + '"], a[href="/stack/' + slug + '"]');
  }

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

